ex = 20 + 70*exp(-0.5);
Ea = cooling_profile(90, @(t) 20, 0.5, 0.1, 10, 'euler');
Eb = cooling_profile(90, @(t) 20, 0.5, 0.05, 20, 'euler');
Ha = cooling_profile(90, @(t) 20, 0.5, 0.1, 10, 'heun');
Hb = cooling_profile(90, @(t) 20, 0.5, 0.05, 20, 'heun');
ex = 20 + 70*exp(-0.5);
rE = abs(Ea(end) - ex) / abs(Eb(end) - ex);
rH = abs(Ha(end) - ex) / abs(Hb(end) - ex);
assert(rE > 1.8 && rE < 2.2, 'Euler is first order');
assert(rH > 3.6 && rH < 4.4, 'Heun is second order');
T0 = cooling_profile(55, @(t) 20, 0.2, 1, 0, 'heun');
assert(isequal(T0, 55), 'zero steps returns the initial value');
threw = false;
try
    cooling_profile(90, @(t) 20, 0.1, 1, 2, 'rk4');
catch
    threw = true;
end
assert(threw, 'unknown method must throw');
